// Admin user manual, served only to signed-in admins by /api/admin/manual.
// Regenerate this file when the manual changes.
export const ADMIN_MANUAL_HTML: string = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"></head><body><title>SNMC Admin Manual</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500;12..96,700&family=Figtree:wght@400;500;600&family=JetBrains+Mono:wght@500&display=swap\" rel=\"stylesheet\">\n<style>\n/* Layout: fixed contents rail on the left, reading column with step-and-screenshot rows on the right. */\n:root{\n  --bg:#f5f8fb; --surface:#ffffff; --ink:#10212f; --muted:#546879; --line:#dbe4ec;\n  --navy:#0b2a4a; --accent:#0a8fb4; --accent-soft:#e1f3f9; --accent-ink:#06607c;\n  --new:#7a3ff2; --new-soft:#efe8fe; --warn:#a85a00; --warn-soft:#fff1de; --ok:#13795b; --ok-soft:#dff4ec;\n  --shadow:0 1px 2px rgba(11,42,74,.06),0 8px 24px rgba(11,42,74,.07);\n  --display:'Bricolage Grotesque','Segoe UI',system-ui,sans-serif; --body:'Figtree','Segoe UI',system-ui,sans-serif; --mono:'JetBrains Mono',ui-monospace,Consolas,monospace;\n}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){\n  --bg:#0a1620; --surface:#101f2c; --ink:#e6eef5; --muted:#9bb0c0; --line:#22384a;\n  --navy:#cfe6f5; --accent:#46c3e6; --accent-soft:#12313f; --accent-ink:#8fdcf3;\n  --new:#b99aff; --new-soft:#2a2046; --warn:#ffb866; --warn-soft:#3a2a12; --ok:#5fd6ae; --ok-soft:#123a2e;\n  --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.35); color-scheme:dark}}\n:root[data-theme=\"dark\"]{\n  --bg:#0a1620; --surface:#101f2c; --ink:#e6eef5; --muted:#9bb0c0; --line:#22384a;\n  --navy:#cfe6f5; --accent:#46c3e6; --accent-soft:#12313f; --accent-ink:#8fdcf3;\n  --new:#b99aff; --new-soft:#2a2046; --warn:#ffb866; --warn-soft:#3a2a12; --ok:#5fd6ae; --ok-soft:#123a2e;\n  --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.35); color-scheme:dark}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth;scroll-padding-top:84px}\nbody{background:var(--bg);color:var(--ink);font:16px/1.65 var(--body);margin:0;-webkit-font-smoothing:antialiased}\na{color:var(--accent-ink)}\n.topbar{position:sticky;top:env(safe-area-inset-top,0px);z-index:30;display:flex;align-items:center;gap:12px;padding:10px 16px;background:color-mix(in srgb,var(--surface) 92%,transparent);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}\n.brand{display:flex;align-items:center;gap:10px;font:700 15px/1.1 var(--display);color:var(--navy);min-width:0}\n.brand i{display:grid;place-items:center;width:30px;height:30px;border-radius:9px;background:var(--navy);color:var(--surface);font:700 13px var(--display);font-style:normal;flex:none}\n.brand span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.spacer{flex:1}\n.btn{border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:10px;padding:7px 12px;font:500 14px var(--body);cursor:pointer}\n.btn:hover{border-color:var(--accent)}\n.menu-btn{display:none}\n.shell{display:grid;grid-template-columns:292px minmax(0,1fr);max-width:1320px;margin:0 auto}\n.rail{position:sticky;top:57px;align-self:start;height:calc(100vh - 57px);overflow:auto;padding:22px 14px 40px 16px;border-right:1px solid var(--line)}\n.search{width:100%;border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:10px;padding:9px 12px;font:15px var(--body);margin-bottom:14px}\n.search:focus{outline:2px solid var(--accent);outline-offset:1px}\n.grp{font:600 11px/1 var(--body);letter-spacing:.09em;text-transform:uppercase;color:var(--muted);margin:18px 8px 8px}\n.rail a{display:flex;gap:10px;align-items:baseline;padding:7px 10px;border-radius:9px;color:var(--ink);text-decoration:none;font-size:14.5px;line-height:1.35}\n.rail a b{font:500 12px var(--mono);color:var(--muted);min-width:20px}\n.rail a:hover{background:var(--accent-soft)}\n.rail a.on{background:var(--accent-soft);color:var(--accent-ink);font-weight:600}\n.rail a.on b{color:var(--accent-ink)}\n.rail a[hidden]{display:none}\n.nomatch{padding:8px 10px;color:var(--muted);font-size:14px}\nmain{padding:0 clamp(16px,4vw,56px) 80px;min-width:0}\n.hero{padding:44px 0 28px}\n.eyebrow{font:500 12px var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--accent-ink)}\nh1{font:700 clamp(34px,5.4vw,58px)/1.02 var(--display);letter-spacing:-.02em;margin:10px 0 14px;color:var(--navy);text-wrap:balance}\n.lede{font-size:18px;color:var(--muted);max-width:60ch;margin:0}\n.hero-meta{display:flex;flex-wrap:wrap;gap:8px;margin-top:20px}\n.chip{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:5px 12px;font-size:13.5px;color:var(--muted)}\n.start{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin:28px 0 8px}\n.start a{display:block;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 18px;text-decoration:none;color:var(--ink);transition:border-color .15s,transform .15s}\n.start a:hover{border-color:var(--accent);transform:translateY(-2px)}\n.start strong{display:block;font:700 16px var(--display);color:var(--navy);margin-bottom:4px}\n.start span{font-size:14px;color:var(--muted)}\nsection{padding-top:56px}\nsection>header{display:flex;align-items:baseline;gap:14px;border-bottom:1px solid var(--line);padding-bottom:12px;margin-bottom:20px}\nsection>header .no{font:500 14px var(--mono);color:var(--accent-ink)}\nh2{font:700 clamp(26px,3.4vw,34px)/1.1 var(--display);letter-spacing:-.015em;margin:0;color:var(--navy);text-wrap:balance}\nh3{font:700 19px/1.25 var(--display);margin:30px 0 8px;color:var(--navy)}\np{margin:0 0 14px;max-width:72ch}\n.row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,340px);gap:32px;align-items:start;margin:18px 0}\n.row.flip{grid-template-columns:minmax(0,340px) minmax(0,1fr)}\n.row.flip .shot{order:-1}\n.row.single{grid-template-columns:minmax(0,1fr)}\n.shot{margin:0;position:sticky;top:76px}\n.frame{background:var(--surface);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);overflow:hidden}\n.frame .bar{display:flex;gap:6px;padding:9px 12px;border-bottom:1px solid var(--line);background:var(--bg)}\n.frame .bar i{width:9px;height:9px;border-radius:50%;background:var(--line)}\n.frame img{display:block;width:100%;height:auto}\nfigcaption{font-size:13px;color:var(--muted);margin-top:8px;line-height:1.4}\nol.steps{list-style:none;counter-reset:s;margin:0 0 14px;padding:0}\nol.steps>li{counter-increment:s;position:relative;padding:0 0 14px 44px;max-width:68ch}\nol.steps>li:before{content:counter(s);position:absolute;left:0;top:0;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent-ink);font:700 13px var(--display)}\nul.list{margin:0 0 14px;padding-left:20px;max-width:68ch}\nul.list li{margin-bottom:7px}\nstrong,b.k{font-weight:600}\n.k{background:var(--accent-soft);color:var(--accent-ink);border-radius:6px;padding:1px 7px;font-weight:600;font-size:.92em;white-space:nowrap}\n.path{font:500 13.5px var(--mono);background:var(--surface);border:1px solid var(--line);border-radius:7px;padding:2px 8px;white-space:nowrap}\n.callout{display:flex;gap:12px;border-radius:12px;padding:13px 16px;margin:16px 0;max-width:72ch;font-size:15px;line-height:1.55}\n.callout b{display:block;font:700 13px var(--body);letter-spacing:.04em;text-transform:uppercase;margin-bottom:2px}\n.callout.tip{background:var(--ok-soft);color:var(--ink)} .callout.tip b{color:var(--ok)}\n.callout.warn{background:var(--warn-soft)} .callout.warn b{color:var(--warn)}\n.callout.new{background:var(--new-soft)} .callout.new b{color:var(--new)}\n.badge{display:inline-block;vertical-align:middle;font:600 11px/1 var(--body);letter-spacing:.06em;text-transform:uppercase;background:var(--new-soft);color:var(--new);border-radius:999px;padding:5px 9px;margin-left:8px}\n.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:12px;background:var(--surface);max-width:760px}\ntable{border-collapse:collapse;width:100%;font-size:15px}\nth,td{text-align:left;padding:11px 16px;border-bottom:1px solid var(--line);vertical-align:top}\nth{font:600 12px var(--body);letter-spacing:.07em;text-transform:uppercase;color:var(--muted);background:var(--bg)}\ntr:last-child td{border-bottom:0}\n.whatsnew{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:12px;margin-top:14px}\n.whatsnew div{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 18px}\n.whatsnew h4{margin:0 0 4px;font:700 16px var(--display);color:var(--navy)}\n.whatsnew p{margin:0;font-size:14.5px;color:var(--muted)}\n.stages{display:flex;flex-wrap:wrap;gap:6px;margin:6px 0 18px;max-width:900px}\n.stages span{font-size:13px;background:var(--surface);border:1px solid var(--line);border-radius:999px;padding:4px 11px;color:var(--muted)}\n.stages span:not(:last-child):after{content:\"\u2192\";margin-left:9px;color:var(--accent)}\nfooter{margin-top:64px;padding-top:20px;border-top:1px solid var(--line);color:var(--muted);font-size:14px}\n.scrim{display:none}\n@media (max-width:980px){\n  .shell{grid-template-columns:minmax(0,1fr)}\n  .menu-btn{display:inline-block}\n  .rail{position:fixed;inset:0 auto 0 0;top:0;height:100%;width:min(310px,86vw);background:var(--bg);z-index:40;transform:translateX(-102%);transition:transform .2s;padding-top:calc(18px + env(safe-area-inset-top,0px))}\n  body.nav-open .rail{transform:none;box-shadow:var(--shadow)}\n  body.nav-open .scrim{display:block;position:fixed;inset:0;background:rgba(0,0,0,.4);z-index:35}\n  .row,.row.flip{grid-template-columns:minmax(0,1fr)}\n  .row.flip .shot{order:0}\n  .shot{position:static;max-width:380px}\n}\n@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}\n@media print{.rail,.topbar,.scrim{display:none}.shell{display:block}}\n</style>\n\n<header class=\"topbar\">\n  <button class=\"btn menu-btn\" id=\"menuBtn\" aria-label=\"Open contents\">Contents</button>\n  <div class=\"brand\"><i>S</i><span>SNMC Admin Manual</span></div>\n  <div class=\"spacer\"></div>\n  <button class=\"btn\" id=\"themeBtn\" aria-label=\"Switch light or dark\">Theme</button>\n</header>\n<div class=\"scrim\" id=\"scrim\"></div>\n\n<div class=\"shell\">\n<nav class=\"rail\" id=\"rail\" aria-label=\"Contents\">\n  <input class=\"search\" id=\"q\" type=\"search\" placeholder=\"Search the manual\" aria-label=\"Search the manual\">\n  <div id=\"navlist\">\n    <div class=\"grp\">Start here</div>\n    <a href=\"#new\"><b>\u2605</b>What's new</a>\n    <a href=\"#s1\"><b>01</b>Logging in</a>\n    <a href=\"#s2\"><b>02</b>Dashboard</a>\n    <div class=\"grp\">Register</div>\n    <a href=\"#s3\"><b>03</b>Nurses &amp; Midwives</a>\n    <a href=\"#s4\"><b>04</b>A person's record</a>\n    <a href=\"#s5\"><b>05</b>Pending Approval</a>\n    <a href=\"#s6\"><b>06</b>License Approval</a>\n    <a href=\"#s7\"><b>07</b>Licence Expiry</a>\n    <a href=\"#s8\"><b>08</b>Licence Renewals</a>\n    <a href=\"#s9\"><b>09</b>Name Changes</a>\n    <div class=\"grp\">Elections</div>\n    <a href=\"#s10\"><b>10</b>Elections &amp; Voting</a>\n    <div class=\"grp\">Analytics</div>\n    <a href=\"#s11\"><b>11</b>Reports</a>\n    <a href=\"#s12\"><b>12</b>Data Export</a>\n    <div class=\"grp\">System</div>\n    <a href=\"#s13\"><b>13</b>Audit Log</a>\n    <a href=\"#s14\"><b>14</b>Admin Users</a>\n    <div class=\"nomatch\" id=\"nomatch\" hidden>No section matches.</div>\n  </div>\n</nav>\n\n<main id=\"top\">\n  <div class=\"hero\">\n    <div class=\"eyebrow\">Seychelles Nurses &amp; Midwives Council \u00b7 October 2026</div>\n    <h1>Admin Platform User Manual</h1>\n    <p class=\"lede\">Everything an administrator needs, from signing in to running an election. Each section shows the page, then the steps.</p>\n    <div class=\"hero-meta\">\n      <span class=\"chip\">snmc.databytes.sc/admin</span>\n      <span class=\"chip\">For administrators</span>\n      <span class=\"chip\">14 sections</span>\n    </div>\n    <div class=\"start\">\n      <a href=\"#s1\"><strong>Sign in</strong><span>Log in and learn the layout.</span></a>\n      <a href=\"#s6\"><strong>Approve licences</strong><span>Confirm categories and upload documents.</span></a>\n      <a href=\"#s10\"><strong>Run an election</strong><span>From nominations to published results.</span></a>\n      <a href=\"#s14\"><strong>Manage users</strong><span>Add admins, reset passwords.</span></a>\n    </div>\n  </div>\n\n  <section id=\"new\">\n    <header><span class=\"no\">\u2605</span><h2>What's new</h2></header>\n    <p>Recent changes that affect your day-to-day work.</p>\n    <div class=\"whatsnew\">\n      <div><h4>Filter the register</h4><p>Show Nurses only, Midwives only, or people who hold both registrations. <a href=\"#s3\">Section 3</a></p></div>\n      <div><h4>Special licence upload</h4><p>Upload a special licence and its document straight from License Approval. <a href=\"#s6\">Section 6</a></p></div>\n      <div><h4>Special licence decisions</h4><p>Approve or reject special licences from a person's record. <a href=\"#s4\">Section 4</a></p></div>\n      <div><h4>Real notification count</h4><p>The bell now shows the exact number of unread items, not \"9+\". <a href=\"#s1\">Section 1</a></p></div>\n      <div><h4>A fuller Audit Log</h4><p>Readable actions, names, IP address and device, with filters. <a href=\"#s13\">Section 13</a></p></div>\n      <div><h4>Simpler new users</h4><p>The email and password you enter are the login, active immediately. <a href=\"#s14\">Section 14</a></p></div>\n    </div>\n  </section>\n\n  <section id=\"s1\">\n    <header><span class=\"no\">01</span><h2>Logging in &amp; getting around</h2></header>\n    <div class=\"row\">\n      <div>\n        <p>Go to <span class=\"path\">snmc.databytes.sc/admin/login</span>, enter your email and password, then choose <span class=\"k\">Sign In</span>.</p>\n        <div class=\"callout warn\"><div><b>Locked out?</b>There is no \"Forgot password\" link. Another administrator with the Admin Users permission resets your password from the Admin Users page (<a href=\"#s14\">Section 14</a>).</div></div>\n        <p>Once signed in, the screen has three parts:</p>\n        <ul class=\"list\">\n          <li><strong>Sidebar</strong> lists every section, grouped as Main, Register, Elections, Analytics and System. You only see the pages your account is allowed to use.</li>\n          <li><strong>Top bar</strong> has a search box that jumps to the register, a notification bell with the exact number of unread items, and <span class=\"k\">Logout</span>.</li>\n          <li><strong>Main area</strong> shows the page you are on.</li>\n        </ul>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"The SNMC Admin sign-in screen\" loading=\"lazy\"></div><figcaption>The admin sign-in screen.</figcaption></figure>\n    </div>\n    <h3>What each permission unlocks</h3>\n    <div class=\"table-wrap\"><table>\n      <tr><th>Permission</th><th>Unlocks</th></tr>\n      <tr><td><strong>Register</strong></td><td>Pending Approval, Licence Expiry, Licence Renewals, Name Change Requests, License Approval</td></tr>\n      <tr><td><strong>Elections</strong></td><td>Elections &amp; Voting</td></tr>\n      <tr><td><strong>Reports</strong></td><td>Reports, Data Export</td></tr>\n      <tr><td><strong>Admin Users</strong></td><td>Audit Log, Admin Users</td></tr>\n      <tr><td><strong>Full Access</strong></td><td>Everything above, whatever the individual permissions say</td></tr>\n    </table></div>\n    <p style=\"margin-top:14px\">The Dashboard and Nurses &amp; Midwives (the register list and each person's record) are open to every signed-in administrator. Every meaningful action you take is written to the <a href=\"#s13\">Audit Log</a> automatically.</p>\n  </section>\n\n  <section id=\"s2\">\n    <header><span class=\"no\">02</span><h2>Dashboard</h2></header>\n    <div class=\"row\">\n      <div>\n        <p>The Dashboard is where you land after signing in. It tells you what needs doing today rather than only showing numbers. There is nothing to edit here, every item is a shortcut.</p>\n        <ol class=\"steps\">\n          <li><strong>Greeting</strong> based on the actual Seychelles time of day.</li>\n          <li><strong>What Needs Your Attention</strong> lists changes awaiting approval, licences expiring within 90 days, renewals awaiting review, election tasks and records needing a confirmed category, each with a <span class=\"k\">Review Now</span> link. If nothing is outstanding, it says so in green.</li>\n          <li><strong>Quick Actions</strong> take you straight to Add Nurse/Midwife, Find Nurse/Midwife, Review Approvals, Licence Renewals, Licence Expiry, Elections, Reports and Export Data.</li>\n          <li><strong>Key Statistics</strong> shows totals such as Total Nurses, Total Midwives, Active Professionals, Pending Approvals and Elections Currently Open. Click a row to open the page it counts.</li>\n          <li><strong>More Detail</strong> expands four charts: Nurses vs Midwives, Register Status, Age Distribution and Gender Distribution.</li>\n        </ol>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Dashboard\" loading=\"lazy\"></div><figcaption>The Dashboard, with items needing attention at the top.</figcaption></figure>\n    </div>\n  </section>\n\n  <section id=\"s3\">\n    <header><span class=\"no\">03</span><h2>Nurses &amp; Midwives</h2></header>\n    <div class=\"row\">\n      <div>\n        <p><span class=\"path\">Register \u2192 Nurses &amp; Midwives</span> is the master list of everyone on file.</p>\n        <ul class=\"list\">\n          <li><span class=\"k\">+ Add New</span> opens the form to register a new person. You can also enter a special licence name and number at the same time.</li>\n          <li><strong>Search</strong> matches on name or registration number.</li>\n          <li><strong>Category filter</strong> <span class=\"badge\">New</span> shows <em>Nurses only</em> (nurse registration, no midwife registration), <em>Midwives only</em>, or <em>Both</em> (holds both). Leave it on \"Nurses &amp; Midwives\" to see everyone.</li>\n          <li><strong>Status filters</strong> narrow by registration status (Practising, Not Practising, Retired, Abroad, Deceased, Deleted, Unknown) and by profile status (Approved, Pending Review, Rejected). Choose <span class=\"k\">Filter</span> to apply.</li>\n          <li>Click <span class=\"k\">Last Name</span> or <span class=\"k\">First Name</span> to sort. Click again to reverse.</li>\n          <li>The list shows 100 people per page. Use <span class=\"k\">Previous</span> and <span class=\"k\">Next</span> to move through.</li>\n          <li><strong>Click a person's name</strong> to open their record (<a href=\"#s4\">Section 4</a>).</li>\n        </ul>\n        <div class=\"callout new\"><div><b>Good to know</b>The filter looks at the registration numbers a person holds, so it works even for records whose category has not been confirmed yet.</div></div>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Nurses and Midwives register list\" loading=\"lazy\"></div><figcaption>The register list. The new Category filter sits beside the status filters.</figcaption></figure>\n    </div>\n  </section>\n\n  <section id=\"s4\">\n    <header><span class=\"no\">04</span><h2>A person's record</h2></header>\n    <div class=\"row\">\n      <div>\n        <p>Open it by clicking a name in the register. Everything about that one person is here.</p>\n        <p><strong>Profile details</strong> cover name, contact information, employer and similar fields. Some can be edited on this page. Registration numbers are never editable, because they identify the person in the register. <strong>Data Source</strong> shows <em>SNMC Masterdatabase</em> for people from the main register.</p>\n        <p>The <strong>Licence Details</strong> table shows the Nurse Licence, Midwife Licence and every Special Licence together.</p>\n        <ul class=\"list\">\n          <li>Each row shows the licence number, expiry date, a computed status (Active, Expiring Soon, Expired) and a link to the document if one is on file.</li>\n          <li><strong>Edit a Nurse or Midwife licence:</strong> click the pencil on that row, change the number or expiry date, then confirm.</li>\n          <li><strong>Add a Special Licence:</strong> choose <span class=\"k\">+ Add Special Licence</span>, then enter the name, number (optional) and issued/expiry dates.</li>\n          <li><strong>Decide on a special licence</strong> <span class=\"badge\">Fixed</span> with <span class=\"k\">Approve</span> or <span class=\"k\">Reject</span>. Upload its supporting document, or <span class=\"k\">Remove</span> it. Decisions appear in the Audit Log.</li>\n        </ul>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Licence Details table on a person's record page\" loading=\"lazy\"></div><figcaption>Licence Details on a person's record.</figcaption></figure>\n    </div>\n    <h3>Record Management</h3>\n    <p>At the bottom of the page, kept apart from everyday actions.</p>\n    <ul class=\"list\">\n      <li><strong>Mark as Deceased</strong> keeps the full record but permanently blocks nomination, voting and renewals. Use it only for someone who has passed away.</li>\n      <li><strong>Permanently Delete Record</strong> is for duplicates and test accounts only. It erases the profile, documents and renewal history and cannot be undone. You must type the person's exact name to confirm. If the platform refuses because the person has real election history (a candidacy, councillor term or nomination), use Mark as Deceased instead.</li>\n    </ul>\n  </section>\n\n  <section id=\"s5\">\n    <header><span class=\"no\">05</span><h2>Pending Approval</h2></header>\n    <div class=\"row\">\n      <div>\n        <p>Changes that nurses and midwives make to their own details (address, phone, employer, licence numbers) need your sign-off before they take effect. This is separate from approving a new registration.</p>\n        <ol class=\"steps\">\n          <li>Use the search box or the <span class=\"k\">All</span>, <span class=\"k\">New \u2014 last 7 days</span> and <span class=\"k\">Older</span> tabs to find a request.</li>\n          <li>Each card shows the person's reason and a before \u2192 after comparison of every field they changed.</li>\n          <li>Choose <span class=\"k\">Approve</span>, optionally add a comment the person can see, then <span class=\"k\">Confirm Approved</span>.</li>\n          <li>Choose <span class=\"k\">Reject</span>. A reason is required and is shown to the person. Then <span class=\"k\">Confirm Rejected</span>.</li>\n        </ol>\n        <p>Nothing changes on the official record until you approve it here.</p>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Pending Approval page\" loading=\"lazy\"></div><figcaption>A pending request with its before and after values.</figcaption></figure>\n    </div>\n  </section>\n\n  <section id=\"s6\">\n    <header><span class=\"no\">06</span><h2>License Approval</h2></header>\n    <div class=\"row\">\n      <div>\n        <p><span class=\"path\">Register \u2192 License Approval</span> is where you confirm whether a person is a Nurse, a Midwife or both, and collect the documents that prove it.</p>\n        <ol class=\"steps\">\n          <li>For each person, use <span class=\"k\">Upload Nurse</span> and/or <span class=\"k\">Upload Midwife</span> to attach their proof of qualification or registration.</li>\n          <li><strong>Special licences:</strong> choose <span class=\"k\">Upload Special Licence</span> <span class=\"badge\">New</span>, type the licence name (for example Critical Care), then pick the file. The licence is added to the person's record and its document is attached. Special licences already on file are listed in the row.</li>\n          <li>Once uploaded, <span class=\"k\">View</span> a document, then <span class=\"k\">Approve</span> or <span class=\"k\">Reject</span> it.</li>\n          <li>Use <span class=\"k\">Confirm as Nurse</span>, <span class=\"k\">Confirm as Midwife</span> or <span class=\"k\">Confirm as Both</span> to finalise the category. Tick several people first to confirm them in one go.</li>\n        </ol>\n        <div class=\"callout tip\"><div><b>Tip</b>Nobody can nominate or vote in a category until it is confirmed here.</div></div>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"License Approval page\" loading=\"lazy\"></div><figcaption>License Approval. Upload Special Licence appears below the Nurse and Midwife uploads.</figcaption></figure>\n    </div>\n  </section>\n\n  <section id=\"s7\">\n    <header><span class=\"no\">07</span><h2>Licence Expiry</h2></header>\n    <div class=\"row\">\n      <div>\n        <p>A monitoring page. There is nothing to approve, it shows who needs to renew.</p>\n        <ol class=\"steps\">\n          <li>Six cards show counts: Expired, Expires in 7, 30, 60 and 90 days, and Active.</li>\n          <li>Click a card to filter the table to that group. Click again to clear.</li>\n          <li>The table lists name, registration number, category, licence type (Nurse, Midwife or a named special licence), expiry date and days remaining, soonest first.</li>\n        </ol>\n        <p>To process a renewal, go to <a href=\"#s8\">Licence Renewals</a> or contact the person.</p>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Licence Expiry summary cards\" loading=\"lazy\"></div><figcaption>The Licence Expiry summary cards.</figcaption></figure>\n    </div>\n  </section>\n\n  <section id=\"s8\">\n    <header><span class=\"no\">08</span><h2>Licence Renewals</h2></header>\n    <div class=\"row\">\n      <div>\n        <p><span class=\"path\">Register \u2192 Licence Renewals</span> lists renewal requests awaiting action.</p>\n        <ol class=\"steps\">\n          <li>A new request shows its submission date and, if attached, a <span class=\"k\">View supporting document</span> link.</li>\n          <li>Choose <span class=\"k\">Start Review</span>. This is a deliberate step: it marks the request \"Under Review\". Open and check the supporting document now. If the step cannot be saved, the card now shows the reason.</li>\n          <li>Only after Start Review do <span class=\"k\">Approve</span> and <span class=\"k\">Reject</span> appear. Pick one, optionally add a comment, then <span class=\"k\">Confirm</span>.</li>\n        </ol>\n        <p>Approving updates the person's official licence expiry date automatically. Rejecting changes nothing.</p>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Licence Renewals page after Start Review\" loading=\"lazy\"></div><figcaption>A renewal after Start Review.</figcaption></figure>\n    </div>\n  </section>\n\n  <section id=\"s9\">\n    <header><span class=\"no\">09</span><h2>Name Change Requests</h2></header>\n    <div class=\"row\">\n      <div>\n        <p>A person asks for a legal name change through their own portal, giving a reason (for example marriage) and usually a supporting document.</p>\n        <ol class=\"steps\">\n          <li>Open <span class=\"path\">Register \u2192 Name Change Requests</span>. Pending requests are listed oldest first, showing old name \u2192 requested name.</li>\n          <li>Choose <span class=\"k\">View supporting document</span> to check the proof, or note that none was attached.</li>\n          <li>Choose <span class=\"k\">Approve</span> or <span class=\"k\">Reject</span>, optionally add a note, then confirm.</li>\n        </ol>\n        <p>The official name changes only when you approve it. Nothing updates automatically.</p>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Name Change Requests page\" loading=\"lazy\"></div><figcaption>Pending name change requests.</figcaption></figure>\n    </div>\n  </section>\n\n  <section id=\"s10\">\n    <header><span class=\"no\">10</span><h2>Elections &amp; Voting</h2></header>\n    <p>The biggest workflow on the platform. A progress bar at the top of every election shows where it stands:</p>\n    <div class=\"stages\"><span>Election Details</span><span>Voting Groups</span><span>Nomination</span><span>Review Nominations</span><span>Candidate Acceptance</span><span>Final Candidate List</span><span>Open Election</span><span>Monitor Voting</span><span>Close Election</span><span>Approval</span><span>Publish</span></div>\n\n    <h3>Create the election</h3>\n    <div class=\"row\">\n      <div>\n        <p>Go to <span class=\"path\">Elections \u2192 Elections &amp; Voting</span>.</p>\n        <ol class=\"steps\">\n          <li>Enter the election name or term (for example 2026\u20132029), the nomination period length and the voting period length, then <span class=\"k\">Next</span>.</li>\n          <li>Review the automatic breakdown of eligible voters by category and sector, then <span class=\"k\">Create Election</span>.</li>\n        </ol>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Elections list and the Create Election wizard\" loading=\"lazy\"></div><figcaption>The Create Election wizard.</figcaption></figure>\n    </div>\n\n    <h3>Set the schedule</h3>\n    <div class=\"row\">\n      <div>\n        <p>On the election's page, set the start and end date and time for Nomination (Round 1) and Voting (Round 2) under <strong>Election Schedule</strong>, then <span class=\"k\">Save Schedule</span>. The system enforces these dates.</p>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Stage stepper and Election Schedule panel\" loading=\"lazy\"></div><figcaption>Stage stepper and Election Schedule.</figcaption></figure>\n    </div>\n\n    <h3>Move it through its stages</h3>\n    <div class=\"row\">\n      <div>\n        <p>Use <span class=\"k\">Advance to \"[next status]\"</span> to progress: Planned \u2192 Nomination Open \u2192 Nomination Closed \u2192 Election Open \u2192 Election Closed \u2192 Completed. Advancing before a round's scheduled close asks you to confirm (<em>Close Early</em>).</p>\n        <p>Need more time? Use <span class=\"k\">Extend</span> next to \"Nomination closes\" or \"Voting closes\". You must give a reason, which is recorded.</p>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Election Controls\" loading=\"lazy\"></div><figcaption>Election Controls: status, publish and extend.</figcaption></figure>\n    </div>\n\n    <h3>Rank nominations and manage candidates</h3>\n    <p>When nominations close, set \"Top N per category\" and choose <span class=\"k\">Rank Nominations</span> to promote the most-nominated candidates. A genuine tie at the cutoff is flagged for you to decide. It is never settled automatically.</p>\n    <p>Each candidate then moves through <span class=\"k\">Select to Progress</span> \u2192 their own <span class=\"k\">Accept</span> or <span class=\"k\">Decline</span> (or you <span class=\"k\">Remove</span> them; declining or removing promotes the next-highest nominee) \u2192 once voting closes, <span class=\"k\">Mark Elected</span> or <span class=\"k\">Not Elected</span>, which is always your decision.</p>\n\n    <h3>Monitor voting</h3>\n    <div class=\"row\">\n      <div>\n        <p>While voting is open, the <strong>Live Election Monitor</strong> shows turnout per category and refreshes every 15 seconds. The <span class=\"k\">Show/Hide Live Results</span> toggle controls whether per-candidate results are visible to administrators. Voters never see running results.</p>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"The Live Election Monitor\" loading=\"lazy\"></div><figcaption>The Live Election Monitor.</figcaption></figure>\n    </div>\n\n    <h3>Disputes and recounts</h3>\n    <div class=\"row\">\n      <div>\n        <p>Once voting closes, choose <span class=\"k\">File a Dispute</span> if something needs investigating, then <span class=\"k\">Run Recount</span> to re-tally independently and compare with the original result.</p>\n        <p>Resolve a dispute with <span class=\"k\">Uphold</span> (a problem is confirmed) or <span class=\"k\">Reject</span> (the original result stands). Both need written notes. An unresolved dispute blocks Minister Approval.</p>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Disputes and Recounts\" loading=\"lazy\"></div><figcaption>Filing a dispute, a recount result and its resolution.</figcaption></figure>\n    </div>\n\n    <h3>Minister Approval and publishing</h3>\n    <div class=\"row\">\n      <div>\n        <p>Choose <span class=\"k\">Record Minister Approval</span>, enter who approved it and any reference or notes, then <span class=\"k\">Confirm Approval</span>. You can then <span class=\"k\">Upload signed Minister Approval document</span>.</p>\n        <p>Only after approval is recorded can you choose <span class=\"k\">Publish Results</span>. It asks for a certification note first, so it cannot happen by accident. Publishing makes the results visible to every nurse and midwife immediately.</p>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Council Review and Minister Approval\" loading=\"lazy\"></div><figcaption>Approval record and signed document upload.</figcaption></figure>\n    </div>\n\n    <h3>Non-voter follow-up</h3>\n    <div class=\"row\">\n      <div>\n        <p>The <strong>Voter Participation</strong> table shows who has and has not voted, never what they voted for. Choose <span class=\"k\">Export Non-Voters</span> to download a CSV for phone or in-person reminders. There is no automatic email or SMS reminder.</p>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"Voter Participation\" loading=\"lazy\"></div><figcaption>Filter to Not Voted Only, or export non-voters.</figcaption></figure>\n    </div>\n  </section>\n\n  <section id=\"s11\">\n    <header><span class=\"no\">11</span><h2>Reports</h2></header>\n    <div class=\"row\">\n      <div>\n        <p><span class=\"path\">Analytics \u2192 Reports</span> builds custom register reports.</p>\n        <ol class=\"steps\">\n          <li>Tick the fields to include (name, registration number, category, expiry dates, age, licence status and more). Sex, Age, Employment Sector, Service Category, Profile Status and Licence Status each reveal a sub-filter.</li>\n          <li>Set the top-level filters: status, category, Has Special Licence and registered date range.</li>\n          <li>Choose <span class=\"k\">Generate Report</span>, then <span class=\"k\">Export CSV</span>, <span class=\"k\">Export Excel</span> or <span class=\"k\">Print / PDF</span>.</li>\n        </ol>\n        <p><span class=\"k\">View Election Reports</span> opens three more report types for each election: <strong>Nomination Report</strong>, <strong>Voting Results</strong> and <strong>Voter Participation</strong> (turnout only, never individual ballots). Each has an <span class=\"k\">Export Excel</span> button.</p>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"The Reports page\" loading=\"lazy\"></div><figcaption>Choose fields, filter, then Generate Report.</figcaption></figure>\n    </div>\n  </section>\n\n  <section id=\"s12\">\n    <header><span class=\"no\">12</span><h2>Data Export</h2></header>\n    <div class=\"row\">\n      <div>\n        <p><span class=\"path\">Analytics \u2192 Data Export</span> downloads whole datasets, as opposed to the filtered reports above. There are 14 dataset cards:</p>\n        <p>Complete Register, Nurse Database, Midwife Database, Licence Database, Expired Licence Database, Licence Renewal Database, Special Licences, Pending Approval Database, Election Database, Candidate Database, Voting Results, Councillor Terms, Admin/User Database and Audit Log (most recent 5,000 entries).</p>\n        <ul class=\"list\">\n          <li>Each card has its own <span class=\"k\">Excel</span> and <span class=\"k\">CSV</span> buttons.</li>\n          <li><span class=\"k\">Export All (Excel)</span> at the top downloads every dataset as one workbook, one sheet per dataset.</li>\n        </ul>\n        <p>Files are generated in your own browser, nothing is sent elsewhere, and every export is recorded in the Audit Log.</p>\n      </div>\n      <figure class=\"shot\"><div class=\"frame\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"data:image/jpeg;base64,\" alt=\"The Data Export page\" loading=\"lazy\"></div><figcaption>14 dataset cards, each with Excel and CSV.</figcaption></figure>\n    </div>\n  </section>\n\n  <section id=\"s13\">\n    <header><span class=\"no\">13</span><h2>Audit Log</h2></header>\n    <p><span class=\"path\">System \u2192 Audit Log</span> is a running record of every meaningful action on the platform. Entries are written automatically. The page is read-only, you only review it. It needs the Admin Users permission.</p>\n    <h3>What each entry shows <span class=\"badge\">Updated</span></h3>\n    <div class=\"table-wrap\"><table>\n      <tr><th>Column</th><th>What it tells you</th></tr>\n      <tr><td><strong>When</strong></td><td>Date and time in Seychelles time</td></tr>\n      <tr><td><strong>Who</strong></td><td>The person who did it (name), or \"System / not signed in\"</td></tr>\n      <tr><td><strong>What</strong></td><td>The action in plain words, for example \"Special licence approved\" or \"Data exported\"</td></tr>\n      <tr><td><strong>Done to</strong></td><td>The person or record it affected, by name</td></tr>\n      <tr><td><strong>From</strong></td><td>IP address, device type, browser and operating system</td></tr>\n      <tr><td><strong>Details</strong></td><td>Readable notes, such as the old and new value of an edited field</td></tr>\n    </table></div>\n    <h3>Filtering</h3>\n    <ul class=\"list\">\n      <li>Pick an <strong>Action</strong> and a <strong>From</strong> and <strong>To</strong> date (Seychelles calendar days), then <span class=\"k\">Apply</span>. <span class=\"k\">Reset</span> clears them.</li>\n      <li>On Admin Users, <em>View activity</em> on a person opens the log filtered to that person.</li>\n    </ul>\n    <div class=\"callout warn\"><div><b>Note</b>The IP and device are recorded for new actions from the day this update goes live. Older entries show a dash. National ID numbers are hidden from administrators without Register permission.</div></div>\n  </section>\n\n  <section id=\"s14\">\n    <header><span class=\"no\">14</span><h2>Admin Users</h2></header>\n    <p><span class=\"path\">System \u2192 Admin Users</span> manages who can use the admin side. It has two lists, <strong>Admin Users</strong> and <strong>Councillors</strong> (the same kind of account, shown separately). Each person has a card showing their sign-in email, permissions and account buttons.</p>\n    <h3>Add a new user <span class=\"badge\">Updated</span></h3>\n    <ol class=\"steps\">\n      <li>Choose the user type and enter full name, email, phone (optional) and title (optional).</li>\n      <li>Enter the <strong>email address</strong> and a <strong>password</strong> of 8 or more characters. They become the person's login exactly as typed. The account is active immediately, the email is already confirmed, and no setup link or email is involved.</li>\n      <li>Tick the permissions that apply (Reports, Register, Elections, Admin Users) or grant <span class=\"k\">Full Access</span>.</li>\n      <li>Choose <span class=\"k\">+ Add New User</span>, then give the person their email and password directly.</li>\n    </ol>\n    <p>If the email already has an account, the platform tells you to use <span class=\"k\">Set Password</span> on that user instead.</p>\n    <h3>Change a password later</h3>\n    <p>On the person's card, choose <span class=\"k\">Set Password</span> to type a specific one, or <span class=\"k\">Random Reset</span> to generate one. Either way the new password is shown once. Copy it and share it directly. It is never emailed and never shown again.</p>\n    <h3>Disable or remove</h3>\n    <p><span class=\"k\">Disable Account</span> blocks sign-in without deleting anything, and can be reversed. <span class=\"k\">Remove</span> takes the account away entirely while keeping its audit history. Neither is available on your own card.</p>\n    <div class=\"callout warn\"><div><b>Permissions are powerful</b>A person with the Admin Users permission can change anyone's permissions, including granting Full Access. Give it only to people you trust with full control.</div></div>\n  </section>\n\n  <footer>SNMC Admin Platform User Manual \u00b7 October 2026 \u00b7 Prepared by Databytes Consultancy Pty Ltd. A separate guide for Councillors and one for Nurses and Midwives are planned.</footer>\n</main>\n</div>\n\n<script>\n(function(){\n  var root=document.documentElement,body=document.body;\n  try{var t=localStorage.getItem('snmc-theme');if(t)root.setAttribute('data-theme',t)}catch(e){}\n  document.getElementById('themeBtn').addEventListener('click',function(){\n    var dark=root.getAttribute('data-theme')==='dark'||(!root.getAttribute('data-theme')&&matchMedia('(prefers-color-scheme: dark)').matches);\n    var next=dark?'light':'dark';root.setAttribute('data-theme',next);\n    try{localStorage.setItem('snmc-theme',next)}catch(e){}\n  });\n  function nav(open){body.classList.toggle('nav-open',open)}\n  document.getElementById('menuBtn').addEventListener('click',function(){nav(true)});\n  document.getElementById('scrim').addEventListener('click',function(){nav(false)});\n  var links=[].slice.call(document.querySelectorAll('#navlist a'));\n  links.forEach(function(a){a.addEventListener('click',function(){nav(false)})});\n  var secs=links.map(function(a){return document.querySelector(a.getAttribute('href'))});\n  var io=new IntersectionObserver(function(es){\n    es.forEach(function(e){if(e.isIntersecting){links.forEach(function(a){a.classList.toggle('on',a.getAttribute('href')==='#'+e.target.id)})}})\n  },{rootMargin:'-20% 0px -70% 0px'});\n  secs.forEach(function(s){if(s)io.observe(s)});\n  var q=document.getElementById('q'),nm=document.getElementById('nomatch');\n  q.addEventListener('input',function(){\n    var v=q.value.trim().toLowerCase(),shown=0;\n    links.forEach(function(a,i){\n      var hit=!v||(a.textContent+' '+(secs[i]?secs[i].textContent:'')).toLowerCase().indexOf(v)>-1;\n      a.hidden=!hit;if(hit)shown++;\n    });\n    document.querySelectorAll('#navlist .grp').forEach(function(g){g.hidden=!!v});\n    nm.hidden=shown>0||!v;\n  });\n  q.addEventListener('keydown',function(e){if(e.key==='Enter'){var f=links.filter(function(a){return !a.hidden})[0];if(f)f.click()}});\n})();\n</script>\n</body></html>";
